import { GrandTestQuestion } from "./grandTestMeta";

export const GRAND_TEST_4: GrandTestQuestion[] = [
  // ── AGRONOMY (6) ──
  { id:"gt4_001", qNo:1,  subject:"agronomy", question:"The 'Soil Health Card' scheme in India was launched in:", options: ["2010", "2015", "2018", "2007"], correct: 1, explanation:"Soil Health Card (SHC) scheme was launched by PM Modi on 19 February 2015 at Suratgarh, Rajasthan. It provides farmers with a report of soil nutrient status and fertiliser recommendations." },
  { id:"gt4_002", qNo:2,  subject:"agronomy", question:"Direct seeded rice (DSR) offers which major advantage over transplanted rice?", options: ["30–35% less water consumption and reduced labour cost", "Better grain quality", "Resistant to all pests", "Higher yield in all soils"], correct: 0, explanation:"DSR (aerobic/wet DSR) reduces water use by 25–35% and eliminates nursery raising and transplanting labour, cutting production cost. Yield may be comparable or slightly lower than transplanted rice in well-managed conditions." },
  { id:"gt4_003", qNo:3,  subject:"agronomy", question:"Nitrogen fixation by free-living bacteria Azotobacter fixes approximately:", options: ["5–20 kg N/ha/year", "150–200 kg N/ha/year", "200–250 kg N/ha/year", "50–75 kg N/ha/year"], correct: 0, explanation:"Azotobacter (free-living, aerobic N-fixer) fixes 5–20 kg N/ha/year under optimum conditions; far less than symbiotic Rhizobium (50–200 kg N/ha). It also produces growth hormones and antifungal compounds." },
  { id:"gt4_004", qNo:4,  subject:"agronomy", question:"Gypsiferous soils require application of gypsum to supply:", options: ["Calcium for alkaline pH correction", "Calcium and sulfur together for improving sodic soils", "Magnesium for chlorophyll synthesis", "Sulfur for micronutrient deficiency"], correct: 1, explanation:"Gypsum (CaSO4.2H2O) applied to sodic soils provides Ca2+ that replaces Na+ on exchange complex, reducing ESP (exchangeable sodium percentage) and soil pH, improving structure. It also supplies sulphur." },
  { id:"gt4_005", qNo:5,  subject:"agronomy", question:"The minimum number of years a crop rotation should continue to break a disease cycle of a soil-borne pathogen is:", options: ["2–3 years", "1 year", "10 years", "5–7 years"], correct: 0, explanation:"Crop rotation of 2–3 years with non-host crops usually breaks the disease/pest cycle for most soil-borne pathogens and most root-feeding pests that have limited survival without host. Longer rotations (5+ yr) for nematodes." },
  { id:"gt4_006", qNo:6,  subject:"agronomy", question:"'Jivamrit' used in natural farming (Zero Budget Natural Farming – ZBNF) is prepared using:", options: ["Cow dung, cow urine, jaggery, legume flour and soil", "Compost tea from crop residues", "Vermicompost and bone meal", "Panchagavya (five cow products)"], correct: 0, explanation:"Jivamrit is a fermented mixture of 10 kg cow dung, 10 litres cow urine, 2 kg jaggery, 2 kg legume flour and a handful of farm soil in 200 litres water; it acts as a soil microbial inoculant." },

  // ── KHARIF CROPS (7) ──
  { id:"gt4_007", qNo:7,  subject:"kharif-crops", question:"Which type of paddy is mostly used for parboiling?", options: ["Any variety can be parboiled equally well", "Medium-grain non-basmati type", "Long-grain fine basmati type", "Short-grain glutinous type"], correct: 1, explanation:"Medium-grain, coarse non-basmati varieties (IR series, MTU varieties) are most commonly parboiled; parboiling improves nutritional value, milling efficiency and reduces breakage during milling." },
  { id:"gt4_008", qNo:8,  subject:"kharif-crops", question:"The critical photoperiod for flowering in many short-day crops is approximately:", options: ["Less than a critical value", "Less than 8 hours of light per day", "More than 16 hours of light", "Exactly 12 hours of light"], correct: 0, explanation:"Short-day plants (SDPs) flower when day length falls below a critical value (typically 12–13 hours). SDPs flower in autumn/winter when days shorten; examples: soybean, cotton, rice, sugarcane." },
  { id:"gt4_009", qNo:9,  subject:"kharif-crops", question:"Soybean (Glycine max) is rich in:", options: ["Vitamin C and iron only", "Simple sugars (40%)", "Starch (70% dry weight)", "Complete protein (35"], correct: 3, explanation:"Soybean is unique among pulses with 35–40% complete protein (all essential amino acids) and 18–20% oil, making it both a protein and oilseed crop — the most produced grain legume worldwide." },
  { id:"gt4_010", qNo:10, subject:"kharif-crops", question:"Which pest of cotton is known as 'jassid' and causes hopper burn?", options: ["Pectinophora gossypiella", "Amrasca biguttula biguttula", "Phenacoccus solenopsis", "Helicoverpa armigera"], correct: 1, explanation:"Cotton jassid (Amrasca biguttula biguttula, Hemiptera: Cicadellidae) causes 'hopper burn' — marginal yellowing and upward curling of leaves due to sap removal and toxin injection; severe attack reddens and dries the plant." },
  { id:"gt4_011", qNo:11, subject:"kharif-crops", question:"Bajra (Pearl millet) is used as a 'catch crop' because:", options: ["It takes longest time to mature", "It is quick", "It has highest protein content", "It is the most expensive crop"], correct: 1, explanation:"Pearl millet (bajra) is a catch crop due to its very fast growth (70–85 days), extreme drought and heat tolerance — it can be sown after a failed crop or late in season to salvage yield." },
  { id:"gt4_012", qNo:12, subject:"kharif-crops", question:"The hormone responsible for stem elongation in sugarcane ratoon crop is:", options: ["Abscisic acid", "Gibberellin", "Auxin", "Cytokinin"], correct: 1, explanation:"Gibberellins (especially GA3) are responsible for internode elongation in sugarcane. Foliar spray of GA3 (50–100 ppm) increases stalk height and cane yield in ratoon crops." },
  { id:"gt4_013", qNo:13, subject:"kharif-crops", question:"Castor (Ricinus communis) seed contains the toxic protein:", options: ["Ricin", "Erucic acid", "Gossypol", "Aflatoxin"], correct: 0, explanation:"Castor seeds contain ricin, one of the most potent natural toxins (inhibits protein synthesis at ribosomal level). Castor meal is detoxified before use as fertilizer. Castor oil (ricinoleic acid, 90%) is non-toxic." },

  // ── RABI CROPS (5) ──
  { id:"gt4_014", qNo:14, subject:"rabi-crops", question:"'WH 147' is a short-duration wheat variety suited for:", options: ["Rain-fed dryland conditions", "High altitude areas", "Late sown conditions due to early maturity", "Timely sown irrigated conditions"], correct: 2, explanation:"WH 147 (Raj 3765) is a late-sown, short-duration wheat variety developed for timely sowing failure (late harvest of preceding kharif crop); it matures in ~105–110 days, escaping terminal heat stress." },
  { id:"gt4_015", qNo:15, subject:"rabi-crops", question:"The oil content of sunflower seed is approximately:", options: ["55–60%", "40–48%", "20–25%", "30–35%"], correct: 1, explanation:"Sunflower achenes (seeds) contain 40–48% oil (confectionery types 26–32%). Sunflower oil is high in linoleic acid (Omega-6, 65%) making it nutritionally valuable; it is India's third largest oilseed crop by area." },
  { id:"gt4_016", qNo:16, subject:"rabi-crops", question:"Wheat 'Karnal bunt' (partial bunt) is caused by:", options: ["Alternaria triticina", "Ustilago tritici", "Puccinia striiformis", "Tilletia indica"], correct: 3, explanation:"Karnal bunt (Tilletia indica/Neovossia indica) is a regulated pest under phytosanitary rules; it partially infects wheat kernels producing a fishy smell, causing quality-based trade rejection rather than yield loss." },
  { id:"gt4_017", qNo:17, subject:"rabi-crops", question:"'Saccharine sorghum' (sweet sorghum) is a type of sorghum used for:", options: ["Silage making only", "Grain production only", "Ethanol/bio", "Fodder production"], correct: 2, explanation:"Sweet sorghum (saccharine sorghum) accumulates fermentable sugars (12–23% Brix) in its stalk juice, making it suitable for ethanol production; it has shorter growing season and lower water requirement than sugarcane." },
  { id:"gt4_018", qNo:18, subject:"rabi-crops", question:"Which of the following is the correct botanical name of mustard?", options: ["Brassica napus", "Brassica juncea", "Brassica rapa", "Brassica oleracea"], correct: 1, explanation:"Indian mustard (rai/sarson) = Brassica juncea; toria = B. rapa; rapeseed = B. napus; kale/cabbage = B. oleracea. B. juncea is the most important oilseed mustard in northern India." },

  // ── GENETICS (7) ──
  { id:"gt4_019", qNo:19, subject:"genetics", question:"The Mendelian ratio 9:3:3:1 in F2 is obtained when:", options: ["Two pairs of linked genes are involved", "One locus shows codominance", "Two pairs of independently assorting genes with complete dominance at each locus", "Genes show incomplete dominance"], correct: 2, explanation:"The 9:3:3:1 ratio (dihybrid ratio) results from crossing two true-breeding parents differing in two traits, with complete dominance and independent assortment of both gene pairs (AaBb × AaBb → F2)." },
  { id:"gt4_020", qNo:20, subject:"genetics", question:"'Quantitative trait locus' (QTL) mapping is used to:", options: ["Determine ploidy level of polyploids", "Identify chromosomal regions containing genes controlling quantitative traits", "Clone specific resistance genes", "Map qualitative traits controlled by single genes"], correct: 1, explanation:"QTL mapping identifies chromosomal regions (loci) associated with quantitative (polygenic) traits like yield, drought tolerance and nutritional quality using molecular markers in segregating populations." },
  { id:"gt4_021", qNo:21, subject:"genetics", question:"Apomixis in plant breeding is commercially valuable because:", options: ["It produces true", "It increases mutation frequency", "It eliminates all diseases from seed", "It creates maximum genetic diversity"], correct: 0, explanation:"Apomixis (asexual seed production) would fix hybrid vigour permanently in seeds, eliminating costly annual hybrid seed production. If transferred to major crops, it would revolutionise agriculture." },
  { id:"gt4_022", qNo:22, subject:"genetics", question:"CRISPR-Cas9 gene editing technology in plant breeding enables:", options: ["Random mutagenesis throughout the genome", "Only gene introduction from foreign species", "Precise editing of target DNA sequences without inserting foreign genes (SDN-1/2)", "Polyploidy induction"], correct: 2, explanation:"CRISPR-Cas9 can precisely cut specific DNA sequences using guide RNA + Cas9 endonuclease. Site-directed nuclease type-1 (SDN-1) creates knockouts/edits at target sites — regulatory status differs from GMOs in many countries." },
  { id:"gt4_023", qNo:23, subject:"genetics", question:"The 'triploid' watermelon (seedless) is developed by treating:", options: ["F1 hybrid seeds with EMS", "Wild diploid species with gibberellin", "Diploid (2x) seedlings with colchicine to produce tetraploid (4x), then crossing 4x♀ × 2x♂", "F2 seeds with gamma radiation"], correct: 2, explanation:"Seedless (triploid) watermelon: (1) colchicine treatment of diploid to get tetraploid (4x); (2) cross tetraploid female × diploid male → triploid (3x) seeds; (3) triploid plant crossed with diploid for pollen — produces seedless fruits." },
  { id:"gt4_024", qNo:24, subject:"genetics", question:"Photoperiodism in plants was first discovered by:", options: ["Garner and Allard", "Went (1928)", "Sachs (1882)", "Darwin (1880)"], correct: 0, explanation:"Garner and Allard (1920) at USDA discovered photoperiodism while studying tobacco var. Maryland Mammoth (which only flowered in autumn regardless of sowing date) — they found day length controlled flowering." },
  { id:"gt4_025", qNo:25, subject:"genetics", question:"'Somaclonal variation' in plant tissue culture refers to:", options: ["Natural variation in seed germination rate", "Cytoplasmic variation only", "Genetic variation arising in plants regenerated from tissue culture", "Variation caused by pathogen infection of cultured tissue"], correct: 2, explanation:"Somaclonal variation: genetic and epigenetic changes (chromosome mutations, transposon activation) that arise during callus culture and plant regeneration; used as a source of novel variation in crop improvement." },

  // ── SEED TECHNOLOGY (4) ──
  { id:"gt4_026", qNo:26, subject:"seed-technology", question:"The 'cold test' for seed vigour simulates:", options: ["High temperature storage conditions", "Early spring cold soil field conditions", "Low humidity drying chamber", "Deep freezing for long-term storage"], correct: 1, explanation:"Cold test: seeds placed in moist medium at 10°C for 7 days then at 25°C for germination. It simulates cold, wet early-spring soil conditions — vigorous seeds germinate normally; weak seeds fail." },
  { id:"gt4_027", qNo:27, subject:"seed-technology", question:"As per Seeds Act 1966, minimum physical purity for certified paddy seed is:", options: ["99%", "95%", "98%", "100%"], correct: 2, explanation:"Indian Seeds Act specifies minimum physical purity (other pure seeds + inert matter) standards; for paddy/rice certified seed, minimum physical purity = 98% (tolerating 2% other matter)." },
  { id:"gt4_028", qNo:28, subject:"seed-technology", question:"Transgenic Bt brinjal seeds are evaluated for:", options: ["Biosafety (human health, environmental safety) and regulatory approval before release", "Seed treatment compatibility only", "Only yield superiority in field trials", "Standard germination test only"], correct: 0, explanation:"Before release of any transgenic (GM) seed, extensive biosafety evaluation (food safety, environmental impact, allergenicity, gene flow risk) and regulatory approval by GEAC (Genetic Engineering Appraisal Committee) is mandatory in India." },
  { id:"gt4_029", qNo:29, subject:"seed-technology", question:"Minimum germination percentage required for certified soybean seed is:", options: ["70%", "80%", "85%", "75%"], correct: 3, explanation:"As per Indian Seeds Act standards, minimum germination for certified soybean seed = 75%. (Paddy/wheat = 80%; maize = 90%; jowar = 80%). These minimum standards must be met for certification." },

  // ── SOIL SCIENCE (5) ──
  { id:"gt4_030", qNo:30, subject:"soil-science", question:"'Gleization' (gleying) in soil formation is associated with:", options: ["Salt accumulation in arid soils", "Arid, well-drained oxidizing conditions", "Waterlogged, anaerobic reducing conditions producing grey-bluish gley colours", "Intense leaching in humid tropical soils"], correct: 2, explanation:"Gleization occurs in waterlogged soils under anaerobic (reducing) conditions; Fe3+ is reduced to Fe2+ (ferrous iron), giving characteristic grey-blue-green gley colours. Organic matter accumulates (peat formation in extreme cases)." },
  { id:"gt4_031", qNo:31, subject:"soil-science", question:"The 'horizon' designation 'Ap' in a soil profile refers to:", options: ["Ploughed or cultivated A horizon", "Parent material horizon", "Accumulation horizon below A", "Original A horizon"], correct: 0, explanation:"'Ap' = A horizon + p (ploughing designation); it is the cultivated or disturbed surface horizon, typically more uniform in colour and structure than an undisturbed A horizon due to mixing by tillage." },
  { id:"gt4_032", qNo:32, subject:"soil-science", question:"Which soil order in USDA taxonomy is characterised by spodic horizon (accumulation of Al, Fe and organic matter)?", options: ["Spodosols", "Ultisols", "Alfisols", "Andisols"], correct: 0, explanation:"Spodosols (Podzols) have a diagnostic spodic horizon — a subsurface horizon with illuviated humus + Al and Fe oxides (organic-mineral complexes) beneath a bleached, ash-grey eluvial (E) horizon." },
  { id:"gt4_033", qNo:33, subject:"soil-science", question:"The process of soil formation is called:", options: ["Pedogenesis", "Edaphology", "Pedoturbation", "Geomorphology"], correct: 0, explanation:"Pedogenesis is the process of soil formation and development from parent material through weathering, organic matter addition, and translocation of materials under the influence of climate, organisms, relief and time." },
  { id:"gt4_034", qNo:34, subject:"soil-science", question:"Sesquioxides in soils are oxides of:", options: ["Iron and aluminium", "Silicon and calcium", "Manganese and titanium", "Potassium and sodium"], correct: 0, explanation:"Sesquioxides = oxides with formula R2O3 (sesqui = 1.5 oxygen per metal): iron sesquioxide (Fe2O3) and aluminium sesquioxide (Al2O3). They give red/yellow colour and are dominant in highly weathered tropical soils." },

  // ── SOIL FERTILITY (5) ──
  { id:"gt4_035", qNo:35, subject:"soil-fertility", question:"The process of nitrogen loss as gas from flooded (anaerobic) soils is called:", options: ["Volatilisation", "Leaching", "Denitrification", "Immobilisation"], correct: 2, explanation:"Denitrification: anaerobic soil bacteria (Pseudomonas, Thiobacillus) reduce NO3− → NO2− → N2O → N2 gas, losing available nitrogen. Significant in waterlogged rice fields and after heavy rain." },
  { id:"gt4_036", qNo:36, subject:"soil-fertility", question:"'Critical limit' of Zn in soil for crops (DTPA-extractable) is:", options: ["2.0 ppm", "1.0 ppm", "0.5 ppm", "5.0 ppm"], correct: 2, explanation:"Critical limit for DTPA-extractable Zn in Indian soils is 0.5 ppm (mg/kg). Below this level, Zn deficiency symptoms appear in sensitive crops and yield is reduced." },
  { id:"gt4_037", qNo:37, subject:"soil-fertility", question:"Phosphate-solubilising bacteria (PSB) make P available by:", options: ["Absorbing P from atmosphere", "Producing organic acids (gluconic, citric) that solubilise insoluble Ca/Fe/Al phosphates", "Producing ammonium that enhances P uptake", "Converting P to gaseous form"], correct: 1, explanation:"PSB (Bacillus megaterium, Pseudomonas fluorescens) produce organic acids (particularly gluconic acid via glucose oxidation) that chelate Ca/Fe/Al and release P from insoluble phosphate compounds." },
  { id:"gt4_038", qNo:38, subject:"soil-fertility", question:"Neem coated urea (NCU) reduces nitrogen loss by:", options: ["Increasing soil pH", "Inhibiting urease enzyme activity, slowing urea hydrolysis", "Killing denitrifying bacteria", "Decreasing soil moisture"], correct: 1, explanation:"Neem oil coating on urea granules contains compounds (nimbidine, nimbin) that inhibit urease enzyme, slowing urea hydrolysis to ammonium, reducing ammonia volatilisation and denitrification, improving NUE by 8–10%." },
  { id:"gt4_039", qNo:39, subject:"soil-fertility", question:"Micronutrient required in lowest amount but essential for reproduction in plants is:", options: ["Manganese", "Zinc", "Iron", "Boron"], correct: 3, explanation:"Boron is required in minute quantities (0.2–0.8 ppm in tissue) and is essential for cell wall synthesis, membrane integrity, sugar transport and pollen germination. Its deficiency-toxicity range is very narrow." },

  // ── ENTOMOLOGY (5) ──
  { id:"gt4_040", qNo:40, subject:"entomology", question:"The pest causing 'frothy (bubbly) mass' on young shoots and grasses is:", options: ["Aphids crop", "Spittlebug (Cercopidae) nymphs", "Whitefly nymphs species", "Leafhoppers variety"], correct: 1, explanation:"Spittlebugs (Cercopidae) nymphs produce a frothy spittle mass by mixing air with liquid excretion from the anus; the froth protects them from desiccation and predators while feeding on plant sap." },
  { id:"gt4_041", qNo:41, subject:"entomology", question:"The egg-laying apparatus in female insects is called:", options: ["Ovipositor", "Tarsus variety", "Cerci plant", "Coxa variety"], correct: 0, explanation:"Ovipositor is the egg-laying organ of female insects, modified from abdominal appendages. It varies widely: long and drill-like in parasitoids and wood wasps, saw-like in sawflies, sting-like in bees and wasps." },
  { id:"gt4_042", qNo:42, subject:"entomology", question:"'Pupal diapause' in Helicoverpa armigera is induced by:", options: ["High rainfall periods", "Host plant toxins", "Host plant deficiency", "Short day length (SD) and low temperature"], correct: 3, explanation:"H. armigera undergoes obligate pupal diapause in cool, short-day conditions (Oct–Feb in northern India), surviving as inactive pupae in soil. This helps the pest survive adverse winter conditions." },
  { id:"gt4_043", qNo:43, subject:"entomology", question:"Coccinella septempunctata (7-spotted ladybird beetle) is a:", options: ["Pollinator of legume crops", "Predator of aphids and mealybugs", "Parasitoid of caterpillars", "Herbivorous pest of all crops"], correct: 1, explanation:"Seven-spotted ladybird (Coccinella septempunctata, Coleoptera: Coccinellidae) is an important aphidophagous (aphid-eating) predator; both adults and larvae consume large numbers of aphids, scale insects and mealybugs." },
  { id:"gt4_044", qNo:44, subject:"entomology", question:"Entomophagous insects are those that:", options: ["Feed on plant pollen only", "Feed on decaying organic matter", "Feed on plant tissues", "Feed on insects (predators or parasitoids)"], correct: 3, explanation:"Entomophagous ('insect-eating') insects include predators (lacewings, ladybirds, ground beetles) that kill and consume prey directly, and parasitoids (Trichogramma, Cotesia) that develop in/on host insects, eventually killing them." },

  // ── CROP PESTS (5) ──
  { id:"gt4_045", qNo:45, subject:"crop-pests", question:"Sucking pests cause damage to crops by:", options: ["Cutting stems at ground level", "Mining inside leaf tissue", "Making holes in seeds during storage", "Extracting cell sap, causing leaf curling, yellowing and virus transmission"], correct: 3, explanation:"Sucking pests (aphids, whiteflies, thrips, jassids, mites) pierce phloem/mesophyll cells and extract sap, removing nutrients, injecting toxins/viruses, causing chlorosis, deformation and reduced photosynthesis." },
  { id:"gt4_046", qNo:46, subject:"crop-pests", question:"The 'Economic Injury Level' (EIL) is:", options: ["Zero pest tolerance in pest-free crop production", "The legal limit for pesticide use in export crops", "The pest density at which we should start spraying pesticides", "The pest density that causes economic loss equal to the cost of control"], correct: 3, explanation:"EIL = the pest population density at which damage cost = cost of the control measure (the management action that should have already been taken at ETL). EIL > ETL always; damage at EIL justifies control cost." },
  { id:"gt4_047", qNo:47, subject:"crop-pests", question:"Root-knot nematode (Meloidogyne spp.) management is best done by:", options: ["Crop rotation with non", "Seed treatment with urea", "Overhead irrigation only", "Foliar insecticide sprays"], correct: 0, explanation:"Root-knot nematode management: crop rotation with non-host crops (marigold, cereals), soil solarisation (plastic mulch, summer months), application of Paecilomyces lilacinus/Pochonia chlamydosporia biocontrol fungi, and resistant varieties." },
  { id:"gt4_048", qNo:48, subject:"crop-pests", question:"The 'termite mound' in agricultural fields causes:", options: ["Natural nitrogen fixation", "Improved soil aeration", "Increased soil organic matter", "Loss of plants by attacking roots and stem base, creating bare patches"], correct: 3, explanation:"Termites (Odontotermes, Microtermes) damage crops by attacking roots, stem bases and stored grain; their mounds with hardened clay compaction create bare circular patches in fields where crops cannot establish." },
  { id:"gt4_049", qNo:49, subject:"crop-pests", question:"'Jassid resistance' in cotton varieties is associated with:", options: ["High gossypol content in leaf", "Thick waxy cuticle on leaf undersurface", "High trichome density on leaf surface", "Red pigmentation in leaves"], correct: 2, explanation:"Cotton varieties with high leaf hair (trichome) density deter jassid (Amrasca biguttula) feeding because hairy leaf surface makes it difficult for the insect to pierce leaf tissue with its stylets." },

  // ── FARM MACHINERY (6) ──
  { id:"gt4_050", qNo:50, subject:"farm-machinery", question:"The 'stroke' in engine terminology refers to:", options: ["Number of cylinders per engine", "Downward movement of piston from TDC to BDC", "Compression ratio of engine", "Firing order of engine"], correct: 1, explanation:"In a reciprocating engine, one 'stroke' = one complete movement of the piston from Top Dead Centre (TDC) to Bottom Dead Centre (BDC) or vice versa. A 4-stroke cycle = 4 strokes = intake, compression, power, exhaust." },
  { id:"gt4_051", qNo:51, subject:"farm-machinery", question:"A chaff cutter (fodder cutter) is used to:", options: ["Cut green/dry fodder into small pieces for better palatability and digestion", "Make hay by drying cut grass", "Remove husks from cereal grain", "Separate grain from chaff using air"], correct: 0, explanation:"Chaff cutters cut fodder (maize stalks, sorghum, grasses, dry straw) into small pieces (1–2 cm), improving palatability, reducing wastage during feeding, and enabling better mixing with concentrate feeds." },
  { id:"gt4_052", qNo:52, subject:"farm-machinery", question:"'Indicated Horse Power' (IHP) of a diesel engine is:", options: ["Power delivered at the PTO shaft", "Power loss in transmission", "Power computed from indicator diagram inside cylinder", "Power at the wheel (DBHP)"], correct: 2, explanation:"IHP (Indicated Mean Effective Pressure × displacement) is the theoretical power developed inside the engine cylinder, calculated from P-V (pressure-volume indicator) diagram. IHP > BHP > DBHP due to friction losses." },
  { id:"gt4_053", qNo:53, subject:"farm-machinery", question:"The primary purpose of the 'land wheel' on a seed drill is:", options: ["To drive the seed metering mechanism through ground contact", "To press seed into soil after dropping", "To steer the seed drill", "To make furrows for seed placement"], correct: 0, explanation:"Land (ground-driven) wheel powers the seed metering mechanism through a chain/gear drive. As the wheel rotates with tractor forward movement, seed cells rotate proportionally, dispensing seed at the set rate." },
  { id:"gt4_054", qNo:54, subject:"farm-machinery", question:"The specific gravity of diesel fuel used in tractors is approximately:", options: ["0.95–1.00", "0.70–0.72", "0.80–0.85", "0.90–0.95"], correct: 2, explanation:"Diesel fuel specific gravity is 0.82–0.87 (typically 0.85 at 15°C). This is higher than petrol (0.70–0.75) but less than water (1.00). Density affects calorific value and injection characteristics." },
  { id:"gt4_055", qNo:55, subject:"farm-machinery", question:"Field efficiency of a tillage implement accounts for:", options: ["Engine power efficiency only", "Fuel efficiency per hectare", "Labour productivity per day", "Proportion of theoretical field capacity actually achieved due to turning, overlaps and stoppages"], correct: 3, explanation:"Field efficiency (%) = (effective field capacity / theoretical field capacity) × 100. Losses include headland turns, overlaps, refuelling stops, adjustments. Most tillage implements achieve 70–85% field efficiency." },

  // ── PLANT PATHOLOGY (9) ──
  { id:"gt4_056", qNo:56, subject:"plant-pathology", question:"Stem rot of paddy (sheath blight) is caused by:", options: ["Xanthomonas oryzae", "Helminthosporium oryzae", "Magnaporthe oryzae", "Rhizoctonia solani AG-1 IA"], correct: 3, explanation:"Sheath blight (ShB) is caused by Rhizoctonia solani AG-1 IA (Basidiomycete), one of the most yield-reducing rice diseases globally; oval/elliptical lesions on sheath progress under high temperature (28–32°C) and dense canopy." },
  { id:"gt4_057", qNo:57, subject:"plant-pathology", question:"'Brown spot' of rice is caused by:", options: ["Cercospora oryzae", "Alternaria alternata", "Phyllosticta oryzicola", "Bipolaris oryzae"], correct: 3, explanation:"Brown spot of rice (Bipolaris oryzae / Cochliobolus miyabeanus) caused Bengal famine of 1943 by destroying 50–90% of rice crop. It appears as oval brown spots with grey centre and dark brown margins on leaves and grains." },
  { id:"gt4_058", qNo:58, subject:"plant-pathology", question:"Downy mildew of pearl millet is caused by:", options: ["Plasmopara viticola", "Pseudoperonospora cubensis", "Peronospora destructor", "Sclerospora graminicola"], correct: 3, explanation:"Green ear disease (downy mildew) of pearl millet is caused by Sclerospora graminicola (Oomycete). Infected panicles are converted into leafy structures ('green ear'); downy sporulation appears on lower leaf surfaces." },
  { id:"gt4_059", qNo:59, subject:"plant-pathology", question:"Plant disease forecasting systems like EPIPRE and FORECASTERR use:", options: ["Soil test results only", "Weather data + crop growth stage + disease incidence data in predictive models", "Crop age alone", "Pesticide application history"], correct: 1, explanation:"Modern disease forecasting systems integrate real-time weather (temperature, humidity, wetness duration), crop growth stage, historical disease pressure and spatial data in simulation models to issue timely alerts." },
  { id:"gt4_060", qNo:60, subject:"plant-pathology", question:"The disease 'citrus greening' (Huanglongbing) is caused by:", options: ["Tristeza Closterovirus", "Xanthomonas axonopodis", "Candidatus Liberibacter asiaticus (bacterial, phloem-limited)", "Phytophthora parasitica"], correct: 2, explanation:"Huanglongbing (HLB / citrus greening) is caused by the phloem-limited α-proteobacteria Candidatus Liberibacter asiaticus, transmitted by Asian citrus psyllid (Diaphorina citri). It is the most destructive citrus disease worldwide." },
  { id:"gt4_061", qNo:61, subject:"plant-pathology", question:"Seed colour reaction in infected sorghum grain indicates:", options: ["Nitrogen deficiency", "Covered kernel smut (Sporisorium sorghi) presence", "Anthracnose infection", "Zinc deficiency"], correct: 1, explanation:"Covered kernel smut (Sporisorium sorghi / Sphacelotheca sorghi) replaces sorghum grains with black teliospore masses enclosed in a thin host membrane; these are only released during threshing — seed treatment prevents it." },
  { id:"gt4_062", qNo:62, subject:"plant-pathology", question:"The principle of 'biological control' of plant diseases relies on:", options: ["Physical exclusion of pathogens only", "Applying chemical toxins to kill pathogens", "Using antibiotics at high concentration", "Using living organisms (antagonists) to suppress pathogen populations and activity"], correct: 3, explanation:"Biological control uses beneficial microorganisms (Trichoderma, Pseudomonas fluorescens, Bacillus subtilis) that antagonise plant pathogens through mycoparasitism, antibiosis, competition and induced systemic resistance (ISR)." },
  { id:"gt4_063", qNo:63, question:"Loose smut of barley is caused by:", subject:"plant-pathology", options: ["Ustilago hordei", "Tilletia caries", "Puccinia hordei", "Ustilago nuda"], correct: 3, explanation:"Loose smut of barley is caused by Ustilago nuda f.sp. hordei (Basidiomycete); all floral parts of infected plants are replaced by loose masses of dark teliospores that disperse at heading. Ustilago hordei causes covered smut." },
  { id:"gt4_064", qNo:64, subject:"plant-pathology", question:"The 'containment' strategy in disease management involves:", options: ["Applying fungicides at pre-set intervals", "Preventing spread of a disease to new areas by quarantine + elimination of infected plants", "Breeding resistant varieties only", "Eradicating all pests from an area permanently"], correct: 1, explanation:"Disease containment: using quarantine (border inspection), phytosanitary measures, destruction of infected hosts and buffer zone restrictions to prevent spread of an epidemic or new pathogen to uninfected areas." },

  // ── AGRICULTURAL ECONOMICS (7) ──
  { id:"gt4_065", qNo:65, subject:"agricultural-economics", question:"The 'terms of trade' for agriculture measures:", options: ["Exchange rate effect on farm income", "Tariff on imported agricultural goods", "Ratio of index of prices received by farmers to index of prices paid by farmers", "Interest rate on agricultural credit"], correct: 2, explanation:"Agricultural terms of trade = index of farm output prices / index of farm input prices (including consumer goods farmers buy). Declining terms of trade (price scissors) means farmers' purchasing power decreases." },
  { id:"gt4_066", qNo:66, subject:"agricultural-economics", question:"The 'Crop Insurance' scheme 'PMFBY' covers:", options: ["Only drought-affected crops", "Only pre-sowing risks", "All risks from pre", "Only post-harvest losses"], correct: 2, explanation:"Pradhan Mantri Fasal Bima Yojana (PMFBY, 2016) provides comprehensive risk coverage from pre-sowing (prevented sowing) through standing crop (pest, drought, flood) to post-harvest losses (14 days after harvest) at low farmer premium." },
  { id:"gt4_067", qNo:67, subject:"agricultural-economics", question:"'Price support' policy for agriculture means:", options: ["Providing zero-interest loans to farmers", "Exempting farm income from all taxes", "Government purchasing commodity at or above announced MSP to support farm income", "Setting market prices by supply-demand only"], correct: 2, explanation:"Price support (floor price) means government intervention by purchasing (through FCI, NAFED, etc.) when market prices fall to or below MSP, preventing farm income collapse and ensuring procurement at guaranteed minimum prices." },
  { id:"gt4_068", qNo:68, subject:"agricultural-economics", question:"'Contract farming' in India under the FAOPA Act 2020 enables:", options: ["Farmers to enter pre", "Compulsory sale through APMC mandis only", "Government to take over private farmland", "Free import of all agricultural commodities"], correct: 0, explanation:"Contract farming (FAOPA) allows farmers to pre-agree price, quantity, quality and delivery terms with sponsors (companies, FPOs) before sowing, reducing market risk — though concerns exist over bargaining power disparity." },
  { id:"gt4_069", qNo:69, subject:"agricultural-economics", question:"The 'Engel's Law' in agricultural economics states:", options: ["As income rises, proportion of income spent on food decreases", "Poor households spend less on food than rich ones", "As income rises, food production increases proportionally", "Agricultural production always follows income growth"], correct: 0, explanation:"Engel's Law (Ernst Engel, 1857): as household income increases, the proportion (share) of income spent on food decreases, while absolute amount may increase. Poor families spend 60–80% on food vs. 10–15% for rich." },
  { id:"gt4_070", qNo:70, subject:"agricultural-economics", question:"'Oligopoly' in agricultural markets means:", options: ["A single buyer controls the market", "Perfect competition among many sellers", "Government controls all prices", "A few large sellers dominate the market"], correct: 3, explanation:"Oligopoly: a few large sellers dominate a market, each aware of others' actions (interdependence). Example: fertiliser market with few manufacturers, or processed food market with few large companies." },
  { id:"gt4_071", qNo:71, subject:"agricultural-economics", question:"'Agri-Infrastructure Fund' (AIF, 2020) of India provides support for:", options: ["PDS (Public Distribution System) godowns only", "Post", "Crop insurance premium subsidy", "Free irrigation infrastructure"], correct: 1, explanation:"AIF (₹1 lakh crore fund) provides medium-long term debt financing with 3% interest subvention for post-harvest infrastructure (cold chains, sorting grading, primary processing) and community farming assets." },

  // ── SURVEYING (4) ──
  { id:"gt4_072", qNo:72, subject:"surveying", question:"'Triangulation' surveying is preferred for:", options: ["Soil profile sampling", "Small field area mapping", "Large", "Garden layout planning"], correct: 2, explanation:"Triangulation networks form the basis of national coordinate systems for large-scale geodetic (country-level) surveys; the primary framework uses high-precision angle measurements from a baseline to progressively cover vast areas." },
  { id:"gt4_073", qNo:73, subject:"surveying", question:"Bearing of a line in surveying is the angle measured:", options: ["Only from south direction", "From true north to the line", "From any arbitrary direction", "From east direction only"], correct: 1, explanation:"Whole circle bearing (WCB) is the clockwise angle from true north (0°/360°) to the survey line. Quadrant bearing is measured from N or S (0°–90°). WCB is more commonly used in Indian surveying practice." },
  { id:"gt4_074", qNo:74, subject:"surveying", question:"The instrument 'levelling staff' (staff gauge) is held vertically during levelling to:", options: ["Measure horizontal distances", "Mark survey stations", "Measure slope gradient", "Obtain a vertical measurement for accurate RL calculation"], correct: 3, explanation:"The levelling staff is a graduated rod held vertically at the survey point; the level reads the staff at the crosshair, giving a staff reading used to calculate height differences and reduced levels (elevations)." },
  { id:"gt4_075", qNo:75, subject:"surveying", question:"'Prismatic compass' measures:", options: ["Temperature and humidity", "Water depth in canals", "Elevation of ground points", "Magnetic bearings of survey lines"], correct: 3, explanation:"The prismatic compass measures whole circle magnetic bearings (0°–360°) of lines in the field; readings are taken on a graduated card through a prism that allows simultaneous sighting and reading. Used in rapid (compass) traversing." },

  // ── FORESTRY (5) ──
  { id:"gt4_076", qNo:76, subject:"forestry", question:"The Van Mahotsav (Forest Festival) in India is celebrated during:", options: ["January", "October", "July", "March"], correct: 2, explanation:"Van Mahotsav (forest festival) was started in 1950 by K.M. Munshi; it is celebrated in the first week of July each year to promote tree planting at the onset of monsoon for maximum seedling survival." },
  { id:"gt4_077", qNo:77, subject:"forestry", question:"Sal (Shorea robusta) forest is predominantly found in:", options: ["Western Ghats", "Thar Desert", "Himalayas above 3000 m", "Sal belt"], correct: 3, explanation:"Sal (Shorea robusta) forms the dominant tropical moist and dry deciduous forest in the sub-Himalayan foothills and eastern India (Odisha, Jharkhand, Bengal, UP, MP). It is India's second most important timber species after teak." },
  { id:"gt4_078", qNo:78, subject:"forestry", question:"'Morinda citrifolia' (Noni) is classified as a:", options: ["Timber tree", "Aromatic grass for perfumery", "Medicinal plant with antioxidant properties", "Nitrogen-fixing tree for agroforestry"], correct: 2, explanation:"Noni (Morinda citrifolia) is a tropical medicinal plant (family Rubiaceae) whose juice is rich in iridoids (particularly iridoid glycosides) claimed to have antioxidant, immunostimulant and pain-relieving properties." },
  { id:"gt4_079", qNo:79, subject:"forestry", question:"'Chipko Movement' (1973, India) was primarily about:", options: ["Grassroots movement to prevent deforestation in Himalayan forests", "Protest against dams on Himalayan rivers", "Agitation for tribal land rights", "Water conservation movement"], correct: 0, explanation:"Chipko (tree-hugging) Movement started in Chamoli, Uttarakhand, 1973 under Sunderlal Bahuguna and Chandi Prasad Bhatt — villagers (mainly women) hugged trees to prevent commercial logging in Himalayan forests." },
  { id:"gt4_080", qNo:80, subject:"forestry", question:"'Lemon grass' (Cymbopogon citratus) is commercially grown for:", options: ["Grain production", "Lemon", "Fodder for cattle", "Soil stabilisation only"], correct: 1, explanation:"Lemon grass yields lemon-scented essential oil (main component: citral 70–85%) used in cosmetics (soaps, perfumes), aromatherapy, food flavouring and mosquito repellents. India is a major global exporter." },

  // ── HORTICULTURE (10) ──
  { id:"gt4_081", qNo:81, subject:"horticulture", question:"'Phytoplasma' diseases in horticultural crops are transmitted by:", options: ["Fungal spores in soil", "Contaminated irrigation water", "Leafhoppers and psyllids", "Mechanical contact by tools"], correct: 2, explanation:"Phytoplasmas (obligate intracellular bacteria in phloem) are transmitted by phloem-feeding Homoptera: mainly leafhoppers (Jassidae) and psyllids. Examples: little leaf of brinjal, big bud of potato, witches' broom." },
  { id:"gt4_082", qNo:82, subject:"horticulture", question:"The best time for harvesting green peas for processing (canning/freezing) is when:", options: ["Pods are fully dry and brown", "Pods are young and pencil thin (before seed fill)", "Tenderometer reading is 100–120 (optimum tenderness)", "Seeds have completely filled the pod to maximum size"], correct: 2, explanation:"Peas for processing are harvested at the 'tenderometer stage' (100–120 units) when sugar content is high and seeds are tender; after this, sugars convert to starch making peas mealy and inferior." },
  { id:"gt4_083", qNo:83, subject:"horticulture", question:"'Hardening' of nursery seedlings before transplanting involves:", options: ["Exposing seedlings to maximum sunlight suddenly", "Increasing irrigation and fertiliser application", "Gradually exposing seedlings to field conditions by reducing water and lowering humidity", "Applying growth retardants to seedlings"], correct: 2, explanation:"Hardening (hardening-off) gradually acclimates greenhouse/nursery-raised seedlings to outdoor conditions (lower humidity, temperature fluctuations, more light, less irrigation) to reduce transplant shock and improve field establishment." },
  { id:"gt4_084", qNo:84, subject:"horticulture", question:"'Curing' in potato post-harvest involves:", options: ["Exposing harvested tubers to 15", "Drying tubers in sun for 3 days", "Chemical treatment with fungicide", "Washing and grading tubers"], correct: 0, explanation:"Potato curing at 15–20°C and 85–90% RH for 10–14 days heals harvest wounds by forming wound periderm (suberin), reducing disease entry and moisture loss during subsequent cold storage." },
  { id:"gt4_085", qNo:85, subject:"horticulture", question:"Controlled Atmosphere (CA) storage for apples maintains:", options: ["Low O2 (1", "Ethylene-enriched atmosphere", "100% N2 with no O2", "High O2 (50%) to maintain colour"], correct: 0, explanation:"CA storage for apples: low O2 (1–3%) reduces respiration; elevated CO2 (3–5%) inhibits ethylene action and delays softening; combined with 0–4°C, it extends storage from 3 months (regular cold) to 9–12 months." },
  { id:"gt4_086", qNo:86, subject:"horticulture", question:"The practice of 'dehorning' in mango involves:", options: ["Removing thorns from the tree", "Applying plant growth regulators to reduce tree height", "Removing male flowers to induce parthenocarpy", "Cutting main branches back to 1"], correct: 3, explanation:"Dehorning (rejuvenation pruning) in old, overgrown mango trees involves cutting back main scaffold branches to 1–1.5 m stubs during dormancy; it stimulates vigorous new growth and restores productivity within 2–3 years." },
  { id:"gt4_087", qNo:87, subject:"horticulture", question:"Mushroom cultivation in India mainly uses which substrate?", options: ["Forest wood logs only", "Paddy straw (for Volvariella) or wheat straw/cotton seed hull (for Agaricus)", "Sugarcane bagasse only", "Sand and gravel mix"], correct: 1, explanation:"Button mushroom (Agaricus bisporus) uses composted wheat straw/paddy straw + chicken manure. Paddy straw mushroom (Volvariella volvacea) grows directly on paddy straw or similar lignocellulosic substrates." },
  { id:"gt4_088", qNo:88, subject:"horticulture", question:"'Chlorosis' as a nutrient deficiency symptom in leaves refers to:", options: ["Necrosis (dead patches) on leaves", "Purpling of leaves and stems", "Browning and drying of leaf tips", "Yellowing of leaves due to reduced chlorophyll"], correct: 3, explanation:"Chlorosis is yellowing or bleaching of leaf tissue due to reduced chlorophyll. Interveinal chlorosis (between veins) suggests Fe, Mn or Zn deficiency (immobile); general yellowing of older leaves suggests N, Mg, S (mobile nutrients)." },
  { id:"gt4_089", qNo:89, subject:"horticulture", question:"The depth of drip irrigation emitter placement for vegetables is typically:", options: ["5 cm below soil surface", "At soil surface", "15–30 cm deep at root zone", "60 cm deep for deep-rooted crops"], correct: 0, explanation:"For vegetables and shallow-rooted crops, drip laterals with emitters are placed at or just below soil surface (0–5 cm) to wet the root zone efficiently; sub-surface drip is placed at 5–15 cm for better evaporation reduction." },
  { id:"gt4_090", qNo:90, subject:"agro-meteorology", question:"Thornthwaite's climate classification system is primarily based on:", options: ["Solar radiation and day length", "Wind speed and humidity", "Mean annual temperature and altitude", "Precipitation relative to potential evapotranspiration (moisture index)"], correct: 3, explanation:"Thornthwaite (1948) classified climates using the moisture index — ratio of annual precipitation to annual PET. It distinguishes humid, sub-humid, semi-arid and arid climates and is widely used in agro-climatic zonation and irrigation planning." },

  // ── AGRICULTURAL EXTENSION (6) ──
  { id:"gt4_091", qNo:91, subject:"extension", question:"The concept of 'felt needs' vs 'real needs' in extension means:", options: ["Government policies vs farmer demands", "Market needs vs household food needs", "Problems farmers articulate themselves vs underlying problems they may not recognise", "Scientific needs determined by researchers vs needs felt by researchers"], correct: 2, explanation:"'Felt needs' are what farmers themselves perceive and express as their problems. 'Real needs' are underlying technical or socioeconomic deficiencies farmers may not recognise; good extension bridges both." },
  { id:"gt4_092", qNo:92, subject:"extension", question:"'Kisan Gosthi' (farmer's meeting) is classified as which type of extension method?", options: ["Individual method", "Mass media method", "Project method", "Group method"], correct: 3, explanation:"Kisan Goshti (farmer's meeting / group discussion) is a group extension method bringing 20–30 farmers together for collective learning, experience sharing and problem solving, offering better reach than individual visits." },
  { id:"gt4_093", qNo:93, subject:"extension", question:"The adoption of innovation by individual farmers follows five stages called:", options: ["Interest → Trial → Evaluate → Scale → Sustain", "Awareness → Interest → Evaluation → Trial → Adoption", "Hear → Watch → Try → Accept → Reject", "Need → Knowledge → Action → Revision → Implementation"], correct: 1, explanation:"The AETA adoption process (Rogers, 1962): Awareness (know it exists) → Interest (seek information) → Evaluation (mental trial) → Trial (small-scale test) → Adoption (full-scale use). Now updated to include confirmation stage." },
  { id:"gt4_094", qNo:94, subject:"extension", question:"National Agricultural Innovation Project (NAIP) was implemented by:", options: ["ICAR with World Bank assistance", "State Agricultural Universities", "Ministry of Rural Development", "NABARD"], correct: 0, explanation:"NAIP (2006–2014) was implemented by ICAR with World Bank loan assistance to promote sustainable agricultural development through competitive grants for consortia-based research and outreach." },
  { id:"gt4_095", qNo:95, subject:"extension", question:"'Agropedia' is:", options: ["An online agricultural knowledge portal in India for farmers", "A crop insurance mobile app", "A fertilizer product range for horticulture", "A textbook series for agricultural graduates"], correct: 0, explanation:"Agropedia (IIT Kanpur + ICAR initiative) is an online agricultural knowledge repository providing ICT-based information on crop production, pest management and market information, accessible in regional languages." },
  // ── GENERAL AGRICULTURE (5) ──
  { id:"gt4_096", qNo:96, subject:"general-agriculture", question:"'Yellow Revolution' in India is associated with:", options: ["Poultry development", "Oilseed production increase", "Maize cultivation", "Banana production"], correct: 1, explanation:"Yellow Revolution refers to the rapid increase in oilseed production in India, particularly during the 1980s–90s through the Technology Mission on Oilseeds (TMO). India became self-sufficient in edible oils during this period." },
  { id:"gt4_097", qNo:97, subject:"general-agriculture", question:"The Seeds Act in India was enacted in:", options: ["1972", "1952", "1960", "1966"], correct: 3, explanation:"The Seeds Act, 1966 regulates the quality of seeds sold in India. It provides for certification, labelling and quality control of seeds of notified varieties. It is administered by the Ministry of Agriculture." },
  { id:"gt4_098", qNo:98, subject:"general-agriculture", question:"The Pradhan Mantri Fasal Bima Yojana (PMFBY) provides:", options: ["Free irrigation facilities", "Crop insurance coverage to farmers", "Minimum price guarantee for all crops", "Subsidised fertilizers to farmers"], correct: 1, explanation:"PMFBY (launched 2016) provides comprehensive crop insurance against all non-preventable natural risks from pre-sowing to post-harvest. Premium is heavily subsidised — farmers pay only 1.5–5% depending on crop season." },
  { id:"gt4_099", qNo:99, subject:"general-agriculture", question:"The Borlaug Global Rust Initiative (BGRI) primarily works on:", options: ["Rice blast disease management", "Soybean mosaic virus control", "Maize streak virus research", "Wheat rust disease surveillance and control"], correct: 3, explanation:"BGRI (established 2008) is a global initiative for early warning, monitoring and developing resistant wheat varieties against stem rust (Ug99), yellow rust and leaf rust — threats to global wheat security." },
  { id:"gt4_100", qNo:100, subject:"general-agriculture", question:"India ranks first in the world in production of:", options: ["Wheat and rice", "Cotton and sugarcane", "Milk and pulses", "Maize and soybeans"], correct: 2, explanation:"India ranks first globally in milk production (23% share) and also leads in pulse production. It is the second largest producer of rice, wheat, sugarcane and cotton — but tops globally in milk and pulses." },
];
